Currently, if a single line in the JSONL file is malformed or partially written, `JSON.parse` will throw an error and cause the entire file parsing to fail, returning an empty list of records.

To make this more robust against individual corrupted lines (which is common in incrementally written log files), we should wrap the parsing of each line in a `try-catch` block.

```typescript
function readJsonLines(pathName: string): { health: "present" | "missing" | "invalid"; records: MetricRecord[] } {
  if (!existsSync(pathName)) {
    return { health: "missing", records: [] };
  }
  try {
    const lines = readFileSync(pathName, "utf8")
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean);
    const records: MetricRecord[] = [];
    for (const line of lines) {
      try {
        const parsed = JSON.parse(line);
        if (isRecord(parsed)) {
          records.push(parsed);
        }
      } catch {
        // Ignore malformed lines to ensure robustness
      }
    }
    return { health: "present", records };
  } catch {
    return { health: "invalid", records: [] };
  }
}
```

